- base-uri 'self';
- img-src 'self' data:;
- script-src 'nonce-<your-nonce>' 'self' 'unsafe-inline' consent.cookiebot.com forte.containers.piwik.pro;
- form-action 'self';
- style-src 'self';
- object-src 'none';
- frame-ancestors 'none';
- connect-src 'self' consent.cookiebot.com consentcdn.cookiebot.com forte.containers.piwik.pro forte.piwik.pro;
